/**
 * 「統計的な推測」ユニットの系列（数Ⅱ・B 第8章）。
 *
 * 背骨設計は docs/statistical_inference_series_design.md（メイン Opus 5・2026-08-16）。
 * 系列1（お手本）はメインが実装し、系列2〜14 は並列委譲＋メイン検収（C15）。
 *
 * 出典: 池田洋介『数学Ⅱ・B 入門問題精講 改訂版』第8章 統計的な推測（旺文社）の
 * 章構成を借り、問題の値・場面はすべてオリジナルに変更（copyright-credit-vs-copy）。
 *
 * ハブ胚細胞（背骨 §1）：
 *   全部は調べられない。だから一部を見て全体を言う——そのとき必ず生まれる「ずれ」を、
 *   消そうとするのではなく、確率という言葉で測ってしまう。ばらつきは、足して平均を
 *   とるたびに √n の分だけ縮み、どんな形の母集団から始めても、その縮みかたは
 *   ただ一つの釣鐘の形へ吸い寄せられる。だから、たった一度の調査から
 *   「この幅の中にあるだろう、これくらいの確からしさで」と言い切れる。
 *   ——確かさとは、ずれが無いことではなく、ずれの大きさが分かっていること。
 *   数Ⅰ・A「データの分析」のハブ（要約とは情報を捨てること）の続きで、
 *   捨てた先で、それでも言えることを確率で保証する。数Ⅱ・B の閉じ石。
 *
 * 入力の折り方（背骨 §2・入力系の拡張は不要）：
 * - 確率・期待値・分散は分数。questionText に「既約分数で」を明記
 * - 標準偏差は「分散を平方数に設計」か「answerDisplay ＋ [sqrt]」の二択のみ
 * - 正規分布表を使う step は、使う表の値を questionText に必ず与える（背骨 D2）
 * - 信頼区間は順序対なので 1 問で両端を答えさせない。d（幅の半分）を主役にする
 * - 判定（棄却するか・独立か）は「判定の根拠そのものの値」へ折る
 *
 * 値設計の掟（背骨 §3・この単元固有）：
 *   (x−m)/σ は表に載る小数第 2 位までの値に。n は平方数。√(p'(1−p')) は有限小数。
 *   表の値は加減算だけで、掛け算で桁を伸ばさない。丸めは「整数の檻」に限る。
 */

