      formulaPreview:
        "欠けた割合 = 1 − 0.1 − 0.2 − 0.4 = 0.3。E(X) = 200/10 = 20 本、E(X²) = 4160/10 = 416 → V(X) = 416 − 400 = 16 → σ(X) = √16 = 4 本",
